-- تسريبات القدرات – الثلاثاء ١٠ نوفمبر ٢٠٢٦
-- 42 سؤالاً: كمي 30 + لفظي 12 (منها 4 في 3 قطع استيعاب)
-- آمن لإعادة التشغيل: guard على وجود أسئلة المجموعة
-- ═══════════════════════════════════════════════════════════════
BEGIN;

INSERT INTO leak_groups (id, title, leak_date, section, question_count, description, is_active, accent_color)
VALUES ('ad101126-2026-4c00-9d00-101120260001', 'تسريبات القدرات – الثلاثاء ١٠ نوفمبر ٢٠٢٦', '2026-11-10', 'mixed', 42, 'أسئلة اختبار القدرات المحوسب ليوم الثلاثاء ١٠ نوفمبر ٢٠٢٦ — القسمان الكمي واللفظي مع الشروح.', true, '#5B21B6')
ON CONFLICT (id) DO NOTHING;

DO $mig$
BEGIN
IF EXISTS (SELECT 1 FROM questions WHERE leak_group_id = 'ad101126-2026-4c00-9d00-101120260001') THEN
  RAISE NOTICE 'أسئلة المجموعة موجودة مسبقاً — تخطي الإدراج';
ELSE
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'ثلاث زجاجات سعتها الإجمالية ٥ لترات، وسعة إحداها ٣ لترات. إذا كانت الزجاجتان الأخريان متساويتين في السعة، فما سعة إحداهما باللتر؟', '["٥", "١", "١٫٥", "٢"]'::jsonb, 1, 'نطرح سعة الزجاجة الكبيرة من السعة الإجمالية: ٥ − ٣ = ٢ لتر. السعة المتبقية موزعة بالتساوي على زجاجتين. إذن سعة كل واحدة = ٢ ÷ ٢ = ١ لتر.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'قارن بين القيمة الأولى ٢⁵ والقيمة الثانية ٥².', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 0, 'الأس يعني عدد مرات ضرب العدد في نفسه. نحسب القيمة الأولى: ٢⁵ = ٢ × ٢ × ٢ × ٢ × ٢ = ٣٢. ونحسب القيمة الثانية: ٥² = ٥ × ٥ = ٢٥. وبما أن ٣٢ > ٢٥، فالقيمة الأولى أكبر.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'ما القيمة التقريبية للتعبير (٠٫٣٣٣ × ٣٫٠٩) ÷ (٣٫٩٤ × ٠٫٧٥)؟', '["١/٤", "١/٣", "١/٥", "١/٢"]'::jsonb, 1, 'لتسهيل الحساب نقرب ٠٫٣٣٣ إلى ١/٣، و٣٫٠٩ إلى ٣، و٣٫٩٤ إلى ٤. يصبح البسط تقريبًا ١، والمقام ٤ × ٠٫٧٥ = ٣. إذن القيمة التقريبية تساوي ١ ÷ ٣ = ١/٣.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الإحصاء والاحتمالات', 'اختيار من متعدد', 'تتوزع ست مواد دراسية بالنسب الآتية: العربي ١٦٪، الإنجليزي ٢٠٪، الرياضيات ٢٠٪، العلوم ١٥٪، الاجتماعيات ١٥٪، الحاسب الآلي ١٤٪. ما المادة ذات النسبة الأقل؟', '["العلوم", "الحاسب الآلي", "الرياضيات", "الاجتماعيات"]'::jsonb, 1, 'لمعرفة المادة الأقل نبحث عن أصغر نسبة بين النسب الست. النسب هي ١٦٪ و٢٠٪ و٢٠٪ و١٥٪ و١٥٪ و١٤٪. أصغرها ١٤٪، وهي نسبة الحاسب الآلي.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'مستطيل أ ب جـ د مرسوم داخل دائرة، وتقع رؤوسه الأربعة على محيطها. أي المعطيات التالية لا يكفي وحده لحساب مساحة الدائرة؟', '["أب = ٨ سم، وأد = ٦ سم", "محيط الدائرة = ١٠π سم", "مجموع قطري المستطيل = ٢٠ سم", "مساحة المستطيل = ٤٨ سم²"]'::jsonb, 3, 'قطر المستطيل المحاط بدائرة يساوي قطر الدائرة. يمكن حسابه من الطول والعرض باستخدام فيثاغورس: √(٨² + ٦²) = ١٠ سم، أو من مجموع القطرين ٢٠ ÷ ٢ = ١٠ سم، كما يمكن إيجاده من محيط الدائرة. أما مساحة المستطيل وحدها فلا تحدد طوله وعرضه، ولذلك لا تكفي لمعرفة قطر الدائرة ومساحتها.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'مثلثان متشابهان، فيهما ضلعان متناظران طولاهما ٢س − ٣ و س + ١، وضلعان متناظران آخران طولاهما ١٢ و٨ على الترتيب. ما قيمة س؟', '["٩", "٨", "٧", "٦"]'::jsonb, 0, 'في المثلثات المتشابهة تكون نسب الأضلاع المتناظرة متساوية. نكتب (٢س − ٣) ÷ (س + ١) = ١٢ ÷ ٨. بالضرب التبادلي: ٨(٢س − ٣) = ١٢(س + ١)، ومنها ١٦س − ٢٤ = ١٢س + ١٢، ثم ٤س = ٣٦، إذن س = ٩.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'ما مجموع قياسات الزوايا الداخلية لخماسي منتظم وسداسي غير منتظم؟', '["٢٢٨°", "٥٤٠°", "٦٠٠°", "١٢٦٠°"]'::jsonb, 3, 'مجموع الزوايا الداخلية لأي مضلع يساوي (عدد أضلاعه − ٢) × ١٨٠°. للخماسي: (٥ − ٢) × ١٨٠ = ٥٤٠°. وللسداسي: (٦ − ٢) × ١٨٠ = ٧٢٠°. المجموع = ٥٤٠ + ٧٢٠ = ١٢٦٠°، ولا يؤثر انتظام المضلع في هذا المجموع.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'تقدم ٥٤٠٠ شخص للحصول على التطعيم، وحصل ٢٠٪ منهم عليه. كم شخصًا إضافيًا يجب أن يحصل على التطعيم ليصبح عدد المطعمين نصف إجمالي المتقدمين؟', '["٢٧٠٠", "١٦٢٠", "١٣٥٠", "١٠٨٠"]'::jsonb, 1, 'نحسب عدد الذين حصلوا على التطعيم أولًا: ٥٤٠٠ × ٢٠ ÷ ١٠٠ = ١٠٨٠ شخصًا. نصف المتقدمين يساوي ٥٤٠٠ ÷ ٢ = ٢٧٠٠ شخص. نطرح المطعمين حاليًا من العدد المطلوب: ٢٧٠٠ − ١٠٨٠ = ١٦٢٠ شخصًا إضافيًا.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الإحصاء والاحتمالات', 'اختيار من متعدد', 'بلغ عدد الإصابات يوم الاثنين ٢١٣ إصابة، ويوم الثلاثاء ٢٢٣ إصابة. ما النسبة المئوية التقريبية للزيادة في عدد الإصابات من الاثنين إلى الثلاثاء؟', '["٥٪", "٨٪", "١٠٪", "١٢٪"]'::jsonb, 0, 'عدد الإصابات يوم الاثنين ٢١٣، ويوم الثلاثاء ٢٢٣. مقدار الزيادة = ٢٢٣ − ٢١٣ = ١٠ إصابات. نحسب نسبة الزيادة مقارنة بيوم الاثنين: ١٠ ÷ ٢١٣ × ١٠٠ ≈ ٤٫٧٪. أقرب اختيار هو ٥٪.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'التحليل', 'اختيار من متعدد', 'كان عدد المرضى يوم السبت ٨٧٠ مريضًا، ثم سُجلت الأعداد الآتية: الأحد ١٢٠، الاثنين ٣٥٧، الثلاثاء ١٨٠، الأربعاء ١٢٩٤، الخميس ١٩٨٧، الجمعة ٦٠٥٨. في كم يوم كان عدد المرضى أقل من اليوم السابق له؟', '["٢", "٣", "٤", "٥"]'::jsonb, 0, 'نقارن عدد المرضى في كل يوم بعددهم في اليوم السابق مباشرة. انخفض العدد من ٨٧٠ يوم السبت إلى ١٢٠ يوم الأحد، ثم ارتفع إلى ٣٥٧ يوم الاثنين. وانخفض مرة ثانية من ٣٥٧ إلى ١٨٠ يوم الثلاثاء، وبعد ذلك ارتفع في بقية الأيام. إذن حدث الانخفاض في يومين.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الإحصاء والاحتمالات', 'اختيار من متعدد', 'قيم ثلاث سنوات متتالية هي ٢٠٤ و١٧٠ و١٩٠. ما المتوسط الحسابي لهذه القيم؟', '["١٨٠", "١٨٥", "١٨٨", "٢٠٠"]'::jsonb, 2, 'المتوسط الحسابي يساوي مجموع القيم مقسومًا على عددها. مجموع القيم الثلاث = ٢٠٤ + ١٧٠ + ١٩٠ = ٥٦٤. نقسم على ٣: ٥٦٤ ÷ ٣ = ١٨٨.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الإحصاء والاحتمالات', 'اختيار من متعدد', 'تُمثَّل ٦٠ كرة ملونة بقطاعات دائرية بحسب ألوانها. إذا كان عدد الكرات البيضاء ١٠ كرات، فما قياس زاوية القطاع الذي يمثلها؟', '["٣٠°", "٤٥°", "٦٠°", "٩٠°"]'::jsonb, 2, 'الدائرة الكاملة قياسها ٣٦٠°، وتتوزع زوايا القطاعات بحسب أعداد الكرات. نصيب الكرات البيضاء = ١٠ ÷ ٦٠ = ١/٦ من الدائرة. إذن زاوية القطاع = ٣٦٠ ÷ ٦ = ٦٠°.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'التحليل', 'اختيار من متعدد', 'كان عدد المرضى يوم السبت ١٨٠ مريضًا، ثم سُجلت الأعداد الآتية: الأحد ١٨٦، الاثنين ٢٦٠، الثلاثاء ١٦٠، الأربعاء ١٨٠، الخميس ٣٢٠، الجمعة ٢١٠. في كم يوم كان عدد المرضى أكبر من اليوم السابق له؟', '["٢", "٣", "٤", "٥"]'::jsonb, 2, 'نقارن كل يوم باليوم السابق له، بدءًا من يوم السبت الذي بلغ فيه العدد ١٨٠. ارتفع العدد يوم الأحد إلى ١٨٦، ثم الاثنين إلى ٢٦٠، وانخفض الثلاثاء إلى ١٦٠. وارتفع مجددًا الأربعاء إلى ١٨٠ والخميس إلى ٣٢٠، ثم انخفض الجمعة إلى ٢١٠. إذن عدد أيام الزيادة ٤.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'احسب محيط مربع إحداثيات رؤوسه (٣، ٣)، (٣، −٢)، (−٢، ٣)، (−٢، −٢).', '["٨", "١٢", "١٨", "٢٠"]'::jsonb, 3, 'طول ضلع المربع يساوي الفرق بين الإحداثيين على المحور نفسه. إذن طول الضلع = ٣ − (−٢) = ٥ وحدات. محيط المربع = ٤ × طول الضلع = ٤ × ٥ = ٢٠ وحدة.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'إذا كان ٣س = ٧ص = ١٠٠، فما قيمة ٦٣س²ص؟', '["١٠٠٠٠٠٠", "٣٠٠٠٠٠٠", "٢١٠٠٠٠٠", "٦٣٠٠٠٠٠"]'::jsonb, 0, 'من المعطيات نجد أن س = ١٠٠ ÷ ٣، وأن ص = ١٠٠ ÷ ٧. بالتعويض: ٦٣س²ص = ٦٣ × (١٠٠ ÷ ٣)² × (١٠٠ ÷ ٧). نختصر ٦٣ مع ٩ × ٧، فيتبقى ١٠٠ × ١٠٠ × ١٠٠ = ١٠٠٠٠٠٠.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'دائرة بداخلها مستطيل طولا ضلعيه ٣ و٤ وحدات، وتقع رؤوسه الأربعة على الدائرة. أوجد محيط الدائرة.', '["٣π", "٤π", "٥π", "٦π"]'::jsonb, 2, 'قطر الدائرة هو نفسه قطر المستطيل الواصل بين رأسين متقابلين. نحسبه بنظرية فيثاغورس: √(٣² + ٤²) = √٢٥ = ٥. محيط الدائرة = القطر × π = ٥π.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'في الشكل مستطيل قُسم ارتفاعه إلى ثلاثة أجزاء متساوية ورُسم قطراه. قارن بين القيمة الأولى، وهي نسبة مساحة الجزء المظلل إلى مساحة المستطيل، والقيمة الثانية ١/٣.', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 2, 'نفرض أن مساحة المستطيل ٩ وحدات، فتكون مساحة كل شريط ٣ وحدات. القطران يتقاطعان في المنتصف، فيحصران في الشريط العلوي شبه منحرف مساحته وحدتان، وهو المظلل في الأعلى. في الشريط السفلي الجزء المحصور بين القطرين وحدتان أيضًا، فيبقى للمثلثين المظللين على الجانبين وحدة واحدة. المظلل كله = ٢ + ١ = ٣ من ٩، أي ١/٣، فالقيمتان متساويتان.', 'https://czzcmbxejxbotjemyuqf.supabase.co/storage/v1/object/public/question-figures/qudurat_nov10_q107_strips.png', 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'إذا كان ٩^ص = ٨١، فقارن بين القيمة الأولى: ص، والقيمة الثانية: ٦.', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 1, 'نبحث عن الأس الذي يجعل العدد ٩ يساوي ٨١ عند رفعه إليه. بما أن ٩ × ٩ = ٨١، فإن ص = ٢. وبمقارنة ٢ مع ٦ نجد أن القيمة الثانية أكبر.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'إذا كان √(١٢ + س²) = ٧، فأوجد قيمة س الموجبة.', '["٦", "√٣٢", "√٣٧", "٧"]'::jsonb, 2, 'نتخلص من الجذر بتربيع طرفي المعادلة، فنحصل على ١٢ + س² = ٤٩. نطرح ١٢ من الطرفين، فيصبح س² = ٣٧. وبأخذ الجذر التربيعي الموجب نجد أن س = √٣٧.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'مثلث قائم الزاوية، قياس إحدى زاويتيه الحادتين س وقياس الأخرى ٤س. أوجد قيمة س بالدرجات.', '["١٦", "١٨", "٣٢", "٣٦"]'::jsonb, 1, 'مجموع زوايا أي مثلث يساوي ١٨٠ درجة. وبما أن إحدى زواياه قائمة، فإن مجموع الزاويتين الأخريين = ١٨٠ − ٩٠ = ٩٠ درجة. إذن س + ٤س = ٩٠، ومنها ٥س = ٩٠، وبالتالي س = ١٨ درجة.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الإحصاء والاحتمالات', 'اختيار من متعدد', 'ما المتوسط الحسابي للأعداد الطبيعية من ٢ إلى ٧٩ شاملًا الطرفين؟', '["٣٤", "٣٥", "٤٠", "٤٠٫٥"]'::jsonb, 3, 'عندما تكون الأعداد متتالية بفارق ثابت، فإن متوسطها الحسابي يساوي متوسط أول عدد وآخر عدد. نعوّض في القانون: المتوسط = (٢ + ٧٩) ÷ ٢. إذن المتوسط = ٨١ ÷ ٢ = ٤٠٫٥.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'اشترت بشرى ٥ أكواب و٦ أطباق، وكان سعر الكوب ٧ ريالات وسعر الطبق ١٠ ريالات. كم ريالًا دفعت بشرى إجمالًا؟', '["٩٠", "٩٥", "١١٥", "١٢٥"]'::jsonb, 1, 'نحسب ثمن الأكواب أولًا: ٥ × ٧ = ٣٥ ريالًا. ثم نحسب ثمن الأطباق: ٦ × ١٠ = ٦٠ ريالًا. نجمع المبلغين: ٣٥ + ٦٠ = ٩٥ ريالًا.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'مع هند ٢٦ هدية، وتريد أن تعطي كل صديقة من صديقاتها ٦ هدايا. ما أكبر عدد من الصديقات يمكنها إعطاؤهن الهدايا بالتساوي؟', '["٣", "٤", "٥", "٦"]'::jsonb, 1, 'نقسم عدد الهدايا على ما ستحصل عليه كل صديقة: ٢٦ ÷ ٦ = ٤ والباقي ٢. هذا يعني أنها تستطيع إعطاء ٤ صديقات ٦ هدايا لكل واحدة. وتتبقى هديتان لا تكفيان لصديقة خامسة.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'أنبوبة طولها ١٢٥ سم، يراد تقسيمها إلى قطع طول كل قطعة منها ٥ سم. احسب عدد القطع الناتجة.', '["١٥", "٢٠", "٢٥", "٣٠"]'::jsonb, 2, 'لإيجاد عدد القطع، نقسم الطول الكلي على طول القطعة الواحدة. نحسب ١٢٥ ÷ ٥ = ٢٥. إذن نحصل على ٢٥ قطعة متساوية الطول.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'إذا كان ٢س أكبر من ص، فقارن بين القيمة الأولى: −٥ص، والقيمة الثانية: −١٠س.', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 0, 'نضرب طرفي العلاقة «٢س أكبر من ص» في ٥، فنحصل على: ١٠س أكبر من ٥ص. عند ضرب الطرفين في عدد سالب ينعكس الترتيب، فيصبح −١٠س أصغر من −٥ص. إذن القيمة الأولى −٥ص هي الأكبر.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'إذا كانت ص عددًا سالبًا، فقارن بين القيمة الأولى: صفر، والقيمة الثانية: −٥ص.', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 1, 'عند ضرب عدد سالب في عدد سالب يكون الناتج موجبًا. وبما أن ص سالبة، فإن −٥ص عدد موجب. وكل عدد موجب أكبر من الصفر، لذلك القيمة الثانية أكبر.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'حديقة مستطيلة الشكل، سارت هند حولها دورة كاملة. إذا كانت المسافة التي قطعتها ٥٠٠ متر، وكان عرض الحديقة ١٠٠ متر، فما طول الحديقة بالمتر؟', '["١٥٠", "١٨٠", "٢٠٠", "٢٥٠"]'::jsonb, 0, 'المسافة المقطوعة حول الحديقة تساوي محيط المستطيل. المحيط = ٢ × (الطول + العرض)، أي ٥٠٠ = ٢ × (الطول + ١٠٠). بقسمة الطرفين على ٢ نجد أن الطول + ١٠٠ = ٢٥٠، وبالتالي الطول = ١٥٠ مترًا.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'عددان الفرق بين مربعيهما يساوي ٣٩، والفرق بينهما يساوي ٣. فما مجموعهما؟', '["٩", "١٠", "١٣", "١٦"]'::jsonb, 2, 'نعتمد على قاعدة الفرق بين مربعين: مربع العدد الأول ناقص مربع العدد الثاني يساوي حاصل ضرب الفرق بينهما في مجموعهما. لذلك ٣٩ = ٣ × مجموع العددين. بقسمة ٣٩ على ٣ نحصل على المجموع = ١٣.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'أسطوانة طول نصف قطر قاعدتها ١ سم، وتدحرجت مسافة ٢٢ سم. قارن بين القيمة الأولى: ١١، والقيمة الثانية: عدد لفات الأسطوانة.', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 0, 'في كل لفة كاملة تقطع الأسطوانة مسافة تساوي محيط قاعدتها. محيط القاعدة = ٢ × π × ١ = ٢π سم، أي نحو ٦٫٢٨ سم. عدد اللفات = ٢٢ ÷ ٦٫٢٨، وهو قريب من ٣٫٥ لفة، وهذا أقل من ١١.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'التحليل', 'اختيار من متعدد', 'اشترك ٢٥ معلمًا و٢٠ مهندسًا و١٨ طبيبًا و١٢ طالبًا في دفع مبلغ إجمالي قدره ١٣٣٠٠ ريال. إذا كان ما دفعه ٥ معلمين يساوي ما دفعه ٤ مهندسين، وما دفعه ١٢ مهندسًا يساوي ما دفعه ٩ أطباء، وما دفعه ٦ أطباء يساوي ما دفعه ٨ طلاب، فما متوسط ما دفعه كل مهندس؟', '["١٩٠", "١٨٠", "١٧٥", "١٧٠"]'::jsonb, 2, 'نحوّل مساهمات الجميع إلى ما يعادل مساهمات المهندسين. مساهمة المعلمين الـ٢٥ تعادل مساهمة ٢٠ مهندسًا، ومساهمة الأطباء الـ١٨ تعادل مساهمة ٢٤ مهندسًا، ومساهمة الطلاب الـ١٢ تعادل مساهمة ١٢ مهندسًا. بإضافة المهندسين الفعليين يصبح المجموع ٢٠ + ٢٠ + ٢٤ + ١٢ = ٧٦ مساهمة متساوية. إذن نصيب المهندس = ١٣٣٠٠ ÷ ٧٦ = ١٧٥ ريالًا.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'التناظر اللفظي', 'اختيار من متعدد', 'قطار : سكة', '["سيارة : أرض", "مياه : مجرى", "سفينة : مرساة", "سماء : طائرة"]'::jsonb, 1, 'القطار يسير على السكة، فهي المسار المخصص لحركته. وكذلك المياه تجري في المجرى، فهو المسار الذي تمر خلاله. أما المرساة فهي أداة لتثبيت السفينة وليست المسار الذي تسير عليه.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'التناظر اللفظي', 'اختيار من متعدد', 'مقود : سيارة', '["دفة : سفينة", "بنك : مصرف", "باب : مزلاج", "طائرة : إشارة"]'::jsonb, 0, 'المقود أداة يستخدمها السائق للتحكم في اتجاه السيارة. والدفة أداة تستخدم للتحكم في اتجاه السفينة. تتطابق العلاقة في كون الكلمة الأولى أداة توجيه للمركبة المذكورة في الكلمة الثانية.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'الخطأ السياقي', 'اختيار من متعدد', 'الشخص الذي يتحمل كثيرًا حين يرضى لن يعود كما كان أبدًا. حدد الكلمة غير المناسبة للسياق.', '["يرضى", "يتحمل", "كثيرًا", "يعود"]'::jsonb, 0, 'الجملة تتحدث عن شخص يصبر ويتحمل الضغوط مدة طويلة، ثم يصل إلى مرحلة يتغير بعدها موقفه. كلمة «يرضى» تعني القبول والاطمئنان، وهي لا تتناسب مع هذه النتيجة. الأنسب كلمة تدل على نفاد الصبر أو بلوغ حد التحمل، مثل «يغضب».', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'الخطأ السياقي', 'اختيار من متعدد', 'رقي المظهر يدل على دماثة الخلق وحسن التربية والبيئة الحسنة. حدد الكلمة غير المناسبة للسياق.', '["المظهر", "الخلق", "التربية", "البيئة"]'::jsonb, 0, 'دماثة الخلق تعني حسن المعاملة ولطف السلوك، وترتبط بالأخلاق والتربية. أما المظهر الخارجي فلا يثبت بالضرورة حسن أخلاق الإنسان. لذلك لا يصح اعتبار رقي المظهر دليلًا قاطعًا على دماثة الخلق.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'الخطأ السياقي', 'اختيار من متعدد', 'الكرام هم الذين يفضلون الموت جوعًا على أن يحفظوا كرامتهم أو يريقوا ماء وجوههم. حدد الكلمة غير المناسبة للسياق.', '["يفضلون", "جوعًا", "يحفظوا", "وجوههم"]'::jsonb, 2, 'المقصود أن أصحاب الكرامة يفضلون تحمل الجوع على فعل شيء يهينهم. عبارة «يحفظوا كرامتهم» تدل على صونها، وهذا أمر محمود لا يُفترض رفضه. لذلك الأنسب «يفقدوا كرامتهم»، حتى يستقيم المعنى مع عبارة «يريقوا ماء وجوههم».', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة من بين الكلمات التالية.', '["إزار", "عقال", "ثوب", "رداء"]'::jsonb, 1, 'الإزار والثوب والرداء أنواع من الملابس التي تغطي أجزاء من الجسم. أما العقال فهو أداة تُلبس فوق غطاء الرأس لتثبيته. لذلك يختلف عن الكلمات الأخرى من حيث وظيفته.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة من بين الكلمات التالية.', '["كتاب", "كرسي", "مكتب", "طاولة"]'::jsonb, 0, 'الكرسي والمكتب والطاولة جميعها من قطع الأثاث. أما الكتاب فهو وسيلة للقراءة والتعلم، وليس قطعة أثاث. لذلك ينتمي إلى فئة مختلفة عن بقية الكلمات.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة من بين الكلمات التالية.', '["تجارة", "نماء", "بذخ", "زيادة"]'::jsonb, 2, 'النماء والزيادة يشيران إلى النمو والازدياد، وقد تؤدي التجارة إلى تحقيقهما. أما البذخ فيعني الإفراط في الإنفاق والترف. ولذلك يختلف عن الكلمات الأخرى المرتبطة بالنشاط الاقتصادي أو النمو.', NULL, 'ad101126-2026-4c00-9d00-101120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'كم عدد الأسباب التي يرى النص أنها قد تؤدي إلى قضم الأظافر؟', '["٤ أسباب", "٣ أسباب", "سببان", "٥ أسباب"]'::jsonb, 0, 'يذكر النص أن الأطباء يعدون التركيز السبب الرئيسي لقضم الأظافر. ثم يشير إلى اعتقادهم بوجود ثلاثة أسباب أخرى. نجمع السبب الرئيسي مع الأسباب الأخرى: ١ + ٣ = ٤ أسباب.', NULL, 'ad101126-2026-4c00-9d00-101120260001', 'e1b10001-2026-4c00-9d00-000000000001', 'قضم الأظافر

يُعد قضم الأظافر عادة تدل على التوتر والقلق، بينما يقول بعض الناس إنها تدل على شدة التركيز. واكتشف الأطباء أن السبب الرئيسي لقضم الأظافر هو التركيز، ويعتقدون أن هناك ثلاثة أسباب أخرى.

وتناول وصف آخر للأشخاص الذين يقضمون أظافرهم ما إذا كان هذا السلوك ناتجًا عن الثقة بالنفس، أو عدم الثقة بالنفس، أو الضغط النفسي، أو كونه دلالة على الشخصية العاطفية.

وتختلف نظرة الناس إلى هذه العادة؛ فبعضهم يراها دليلًا على ضعف الشخصية، بينما يرى آخرون أنها تدل على ذكاء الشخص أو دخوله في علاقة عاطفية.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
