DO $chk$
DECLARE n INT; nq INT; nv INT;
BEGIN
  SELECT COUNT(*) INTO n FROM questions WHERE leak_group_id = 'ad101126-2026-4c00-9d00-101120260001';
  SELECT COUNT(*) INTO nq FROM questions WHERE leak_group_id = 'ad101126-2026-4c00-9d00-101120260001' AND section = 'quant';
  SELECT COUNT(*) INTO nv FROM questions WHERE leak_group_id = 'ad101126-2026-4c00-9d00-101120260001' AND section = 'verbal';
  RAISE NOTICE 'إجمالي: % — كمي: % — لفظي: %', n, nq, nv;
  IF n <> 42 THEN RAISE EXCEPTION 'عدد الأسئلة % لا يطابق المتوقع 42', n; END IF;
